/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('orders')` (or `ctx.tryUse` for an optional dependency). */
export interface OrdersPublicApi {
  /** Create the order from an authorized or pending payment. Freezes catalog.snapshotForOrder and offers.snapshotForOrder per item. Status open when paymentState=accepted (publishes orders.order.placed and orders.order.accepted in one transaction), payment_pending otherwise (publishes orders.order.placed only). Idempotent per checkoutSessionId: a second call returns the existing order. Used by: checkout. */
  createOrder(input: OrderCreateInput): Promise<OrderDetail>;
  /** payment_pending → open when the payment result arrives (also done on payments.payment.authorized). Idempotent. Used by: checkout. */
  acceptOrder(orderId: string, paymentIntentId: string): Promise<OrderDetail>;
  /** payment_pending → cancelled when a pending payment is finally declined (also done on payments.payment.failed). Used by: checkout. */
  cancelForDeclinedPayment(orderId: string): Promise<void>;
  /** Full order for other modules (no access check) Used by: payments, shipping, returns, support, finance, messaging, warehouse, reviews. */
  getOrder(orderId: string): Promise<OrderDetail | null>;
  /** Seller group with ship-to address, delivery promise, dispatch deadline and items still to ship Used by: shipping, warehouse, fulfillment-service. */
  getFulfillmentTask(groupId: string): Promise<FulfillmentTask>;
  /** Items belong to the group, are not cancelled or already shipped, and quantities fit Used by: shipping, warehouse. */
  canShipItems(groupId: string, lines: { orderItemId: string, quantity: number }[]): Promise<{ ok: boolean, problems: string[] }>;
  /** Recalculated deadline (e.g. a payment accepted late) or a staff extension; publishes orders.dispatch_deadline.changed Used by: shipping. */
  setDispatchDeadline(groupId: string, dueAt: string, reason: string, actor: common.Actor): Promise<void>;
  /** Per item: paid amount split into item, discount share, shipping share and tax share, for refund caps Used by: payments, returns, support. */
  getPaidAmounts(orderId: string): Promise<ItemPaidAmount[]>;
  /** Match a guest order by reference and checkout email (case-insensitive); used by the guest lookup Used by: customers. */
  findGuestOrder(orderRef: string, email: string): Promise<{ orderId: string } | null>;
  /** Guest orders for emailed order links Used by: customers. */
  listGuestOrdersByEmail(email: string): Promise<{ orderId: string, ref: string, placedAt: string }[]>;
  /** Account overview tile Used by: customers. */
  countInProgress(customerId: string): Promise<{ inProgress: number, delayedPackages: number }>;
  /** Account overview recent orders Used by: customers. */
  listRecentForCustomer(customerId: string, limit: number): Promise<OrderSummary[]>;
  /** Account overview delay alerts with new estimate and options Used by: customers. */
  listDelayedItemsForCustomer(customerId: string): Promise<DelayedItemAlert[]>;
  /** Units bought recently, for per-customer purchase limits Used by: checkout, promotions. */
  countPurchased(customerId: string, offerId: string, sinceDays: number): Promise<number>;
  /** Delivered purchase of the product for Verified Purchase labels Used by: reviews. */
  isVerifiedPurchase(customerId: string, productId: string): Promise<{ orderItemId: string, deliveredAt: string } | null>;
  /** Store order detail by reference. Returns the order only when it belongs to the signed-in customer or the guest session has access (identity.hasGuestOrderAccess); otherwise null (NOT_FOUND). Used by: graphql. */
  getOrderForViewer(viewer: { customerId?: string, guestSessionId?: string }, ref: string): Promise<OrderDetail | null>;
  /** Order history with search, date range and status tab (same filters as GET /orders); fields are resolved lazily so list cards stay cheap Used by: graphql. */
  listOrdersForCustomer(customerId: string, filter: { q?: string, range?: string, from?: string, to?: string, tab?: string }, page: common.PageInput): Promise<common.Page<OrderDetail>>;
  /** Counts per status tab plus delayed packages (account overview tiles, order list tabs, customer 360) Used by: graphql. */
  countOrdersByTab(customerId: string, range?: string): Promise<{ all: number, inProgress: number, delivered: number, returns: number, cancelled: number, delayedPackages: number }>;
  /** One order as a seller sees it: only the seller's own groups (items, money, ship-to while needed, cancellations, timeline) and seller-safe order fields. Null (NOT_FOUND) when the order has no group of this seller. Used by: graphql. */
  getOrderForSeller(sellerId: string, ref: string): Promise<{ order: OrderDetail, groups: SellerOrderDetail[] } | null>;
  /** The seller's orders by stage with dispatch deadlines (same filters as seller GET /orders); own groups only Used by: graphql, search. */
  listOrdersForSeller(sellerId: string, filter: { tab?: string, tabs?: string[], q?: string, placedFrom?: string, placedTo?: string, overdueOnly?: boolean, sort?: string }, page: common.PageInput): Promise<common.Page<{ order: OrderDetail, groups: SellerOrderDetail[] }>>;
  /** Seller tab counts plus overdue and due today Used by: graphql. */
  countSellerOrders(sellerId: string): Promise<SellerOrderCounts>;
  /** Order 360 across sellers for staff: groups, items, money by seller, after-sales, flags, notes and staff history. Contact details masked unless orders.customers.view-contact. Used by: graphql. */
  getOrderAdmin(ref: string): Promise<AdminOrderDetail | null>;
  /** Staff order list (same filters as admin GET /orders plus customerId) for the customer and seller 360 views Used by: graphql, search. */
  listOrdersAdmin(filter: { q?: string, sellerType?: string, sellerId?: string, customerId?: string, fulfillmentStatus?: string, paymentState?: string, placedFrom?: string, placedTo?: string, flag?: string, savedFilterId?: string }, page: common.PageInput): Promise<common.Page<AdminOrderDetail>>;
  /** Batched order lookup for order fields on other modules' records (Case.order, Return.order, RefundRequest.order). Same visibility as order / sellerOrder / orderAdmin: store → only orders of the signed-in customer or a guest session with access; seller → only the caller's own groups and seller-safe fields (null when the order has no group of this seller); admin → order 360 (contact masked unless orders.customers.view-contact). Not visible → null (never an error that reveals the order exists). Used by: graphql. */
  getOrdersByIds(viewer: { area: 'store'|'seller'|'admin', customerId?: string, guestSessionId?: string, sellerId?: string }, orderIds: string[]): Promise<Record<string, OrderDetail | { order: OrderDetail, groups: SellerOrderDetail[] } | AdminOrderDetail | null>>;
  /** Seller 360 order tiles (staff): open orders (a group of the seller not yet delivered or cancelled), groups past their dispatch deadline, due today, pending customer cancellation requests and cancellations in the last 30 days. Recent orders use listOrdersAdmin with filter.sellerId. Used by: graphql. */
  countOrdersForSellers(sellerIds: string[]): Promise<Record<string, { open: number, overdueDispatch: number, dueToday: number, cancellationRequests: number, cancellations30d: number }>>;
  /** Export rows for reports datasets orders.admin.orders and orders.seller.orders (seller rows are the seller's own groups; customer email and phone masked without orders.customers.view-contact) Used by: reports. */
  exportRows(dataset: string, filters: unknown, principal: identity.Principal, cursor?: string): Promise<{ rows: unknown[], nextCursor?: string }>;
  /** Order items per product from the purchase snapshots: open (not yet delivered, cancelled or refunded) and past (everything else). Catalog publication-impact and merge previews. Used by: catalog. */
  countOrderItemsForProducts(productIds: string[]): Promise<Record<string, { open: number, past: number }>>;
  /** Orders placed before the date with at least one item in the category (snapshot category, subcategories included) that is not yet delivered, cancelled or refunded. Returns category-exception preview. Used by: returns. */
  countOpenOrdersInCategory(categoryId: string, placedBefore: string): Promise<{ orders: number, items: number }>;
}

/* ------------------------------------------------------------------ tables (Kysely row types) */

/** Tables in the `orders` schema. Use with `ctx.db` (already scoped to the schema). */
export interface OrdersDb {
  /** One per checkout */
  orders: {
    id: string;
    /** MK-YYMMDD-NNNNN */
    ref: string;
    checkout_session_id: string;
    customer_id: string | null;
    contact_email: string;
    contact_phone: string | null;
    contact_name: string;
    channel: string;
    lifecycle: 'payment_pending' | 'open' | 'completed' | 'cancelled';
    display_status: string;
    flags: Json;
    currency: string;
    items_total: number;
    discount_total: number;
    shipping_total: number;
    tax_total: number;
    total: number;
    delivery_address: Json;
    gift_note: string | null;
    hide_prices: boolean;
    /** AcceptedPolicyVersion[] */
    policy_versions: Json;
    coupon_codes: Json;
    payment_intent_id: string;
    payment_state: string;
    payment_method_label: string;
    captured_total: number;
    refunded_total: number;
    placed_at: Date;
    accepted_at: Date | null;
    completed_at: Date | null;
    /** ref, contact, product titles, tracking numbers */
    search: string | null;
  };
  /** One per seller package; the seller's fulfillment task */
  seller_groups: {
    id: string;
    order_id: string;
    position: number;
    owner_type: string;
    seller_id: string | null;
    seller_name: string;
    ships_from: string;
    fulfilled_by: string;
    /** DeliveryPromise */
    delivery: Json;
    dispatch_by: Date;
    dispatch_by_history: Json;
    status: string;
    return_terms_summary: string;
    items_total: number;
    discount_total: number;
    shipping_total: number;
    tax_total: number;
    total: number;
    shipped_at: Date | null;
    delivered_at: Date | null;
  };
  /** Item lines with state and frozen snapshots; partial actions split lines */
  order_items: {
    id: string;
    order_id: string;
    group_id: string;
    offer_id: string;
    product_id: string;
    variant_id: string;
    stock_item_id: string;
    /** catalog.ProductSnapshot */
    product_snapshot: Json;
    /** offers.OfferSnapshot */
    offer_snapshot: Json;
    return_terms: Json;
    quantity: number;
    unit_price: number;
    discounts: Json;
    shipping_share: number;
    tax_share: number;
    paid_amount: number;
    refunded_amount: number;
    refund_status: string;
    state: string;
    state_before_request: string | null;
    shipment_id: string | null;
    return_id: string | null;
    return_ref: string | null;
    delivered_at: Date | null;
    return_window_ends_at: Date | null;
    split_from_item_id: string | null;
    replacement_of_item_id: string | null;
    checkout_line_id: string;
  };
  /** Every item state change */
  item_state_log: {
    id: string;
    item_id: string;
    from_state: string;
    to_state: string;
    event: string;
    reason: string | null;
    actor_kind: string;
    actor_id: string | null;
    at: Date;
  };
  /** Cancellation requests and direct cancellations */
  cancellations: {
    id: string;
    order_id: string;
    group_id: string;
    initiated_by: string;
    reason_code: string;
    reason: string | null;
    items: Json;
    status: string;
    respond_by: Date | null;
    decided_by: Json | null;
    decided_at: Date | null;
    decline_reason: string | null;
    refund_preview: Json;
    refund_status: string;
    payment_refund_id: string | null;
    idempotency_key: string | null;
    created_at: Date;
  };
  /** Projection of shipping events for display, search by tracking number and flags */
  shipment_refs: {
    shipment_id: string;
    order_id: string;
    group_id: string;
    package_label: string;
    carrier: string | null;
    service: string | null;
    tracking_number: string | null;
    tracking_url: string | null;
    status: string;
    estimated_arrival: Json | null;
    shipped_at: Date | null;
    delivered_at: Date | null;
    item_ids: Json;
  };
  /** Customer-visible events and staff action history */
  timeline: {
    id: string;
    order_id: string;
    group_id: string | null;
    item_id: string | null;
    visibility: 'customer' | 'seller' | 'staff';
    label: string;
    detail: string | null;
    reason: string | null;
    actor_kind: string;
    actor_id: string | null;
    actor_name: string | null;
    at: Date;
  };
  /** Internal staff notes */
  notes: {
    id: string;
    order_id: string;
    text: string;
    author_id: string;
    author_name: string;
    at: Date;
  };
  /** Issued receipt and invoice numbers; PDFs render from the frozen order on request */
  documents: {
    id: string;
    order_id: string;
    group_id: string | null;
    kind: string;
    number: string;
    issued_at: Date;
  };
  saved_filters: {
    id: string;
    owner_staff_id: string;
    name: string;
    query: Json;
    shared: boolean;
    cached_count: number | null;
    counted_at: Date | null;
    created_at: Date;
  };
  /** Daily counters for MK-YYMMDD-NNNNN */
  ref_sequences: {
    day: string;
    last_value: number;
  };
}

